+public:
+  SynchronizationAnalysis(Allocation &allocation, BufferRegionAnalysis &regions,
+                          llvm::SmallPtrSetImpl<Operation *> &scalarOps)
+      : MembarAnalysis(allocation, nullptr, regions), scalarOps(scalarOps) {}
