+  // First warp barrier that a later CTA barrier can make redundant.
+  Operation *firstWarpBarrier = nullptr;
+  llvm::SmallPtrSet<Operation *, 16> foldableOps;
+  llvm::SmallPtrSetImpl<Operation *> &scalarOps;
+};
